import React from 'react';
import { useEffect, useRef, useState } from 'react';
import { Network } from 'vis-network/standalone';
import { DataSet } from 'vis-data/standalone';

interface CharacterNode {
  id: string;
  label: string;
  title: string;
  image?: string;
  shape: string;
  size: number;
  font: {
    size: number;
    color: string;
    face: string;
    background: string;
  };
  borderWidth: number;
  borderWidthSelected: number;
  color: {
    border: string;
    background: string;
    highlight: {
      border: string;
      background: string;
    };
  };
}

interface RelationshipEdge {
  id: string;
  from: string;
  to: string;
  label: string;
  title: string;
  width: number;
  color: {
    color: string;
    highlight: string;
  };
  arrows: {
    to: {
      enabled: boolean;
      scaleFactor: number;
    };
  };
}

interface CharacterNetworkProps {
  data: any;
  onSelectCharacter?: (characterId: string) => void;
  height?: string;
}

const CharacterNetwork: React.FC<CharacterNetworkProps> = ({ 
  data, 
  onSelectCharacter,
  height = '600px'
}) => {
  const networkRef = useRef<HTMLDivElement>(null);
  const [network, setNetwork] = useState<Network | null>(null);

  useEffect(() => {
    if (!networkRef.current || !data || !data.characters) return;

    // 准备节点数据
    const nodes = new DataSet<CharacterNode>(
      data.characters.map((character: any) => ({
        id: character.id,
        label: character.name,
        title: `<div style="padding: 10px; max-width: 200px;">
                  <div style="font-weight: bold; font-size: 16px;">${character.name}</div>
                  <div style="color: #666; margin: 5px 0;">${character.title}</div>
                  <div style="margin-top: 5px;">${character.description}</div>
                </div>`,
        image: character.avatar ? `/images/characters/${character.avatar}` : undefined,
        shape: 'circularImage',
        size: character.id === 'hanlixiu' ? 40 : 30, // 主角更大
        font: {
          size: 14,
          color: '#ffffff',
          face: 'Arial',
          background: 'rgba(0, 0, 0, 0.7)'
        },
        borderWidth: 3,
        borderWidthSelected: 5,
        color: {
          border: character.id === 'hanlixiu' ? '#e6194b' : '#3498db',
          background: character.id === 'hanlixiu' ? '#e6194b' : '#3498db',
          highlight: {
            border: character.id === 'hanlixiu' ? '#ff0000' : '#2980b9',
            background: character.id === 'hanlixiu' ? '#ff0000' : '#2980b9'
          }
        }
      }))
    );

    // 准备边数据
    const edges = new DataSet<RelationshipEdge>();
    let edgeId = 1;

    data.characters.forEach((character: any) => {
      if (character.relationships) {
        character.relationships.forEach((rel: any) => {
          // 查找关系类型的颜色
          const relType = data.relationshipTypes.find((t: any) => t.type === rel.type);
          const color = relType ? relType.color : '#999999';

          edges.add({
            id: `e${edgeId++}`,
            from: character.id,
            to: rel.target,
            label: rel.type,
            title: rel.description,
            width: 2,
            color: {
              color: color,
              highlight: color
            },
            arrows: {
              to: {
                enabled: false,
                scaleFactor: 0.5
              }
            }
          });
        });
      }
    });

    // 网络配置
    const options = {
      nodes: {
        borderWidth: 2,
        shadow: true,
        shapeProperties: {
          useBorderWithImage: true
        }
      },
      edges: {
        smooth: {
          type: 'continuous',
          forceDirection: 'none',
          roundness: 0.5
        },
        font: {
          size: 12,
          align: 'middle',
          background: 'rgba(255, 255, 255, 0.7)'
        }
      },
      physics: {
        stabilization: {
          iterations: 100
        },
        barnesHut: {
          gravitationalConstant: -2000,
          centralGravity: 0.1,
          springLength: 150,
          springConstant: 0.05,
          damping: 0.09
        }
      },
      interaction: {
        hover: true,
        tooltipDelay: 200,
        hideEdgesOnDrag: true,
        navigationButtons: true,
        keyboard: true
      }
    };

    // 创建网络
    const newNetwork = new Network(
      networkRef.current,
      { nodes, edges },
      options
    );

    // 点击事件
    newNetwork.on('selectNode', (params) => {
      if (params.nodes.length > 0 && onSelectCharacter) {
        onSelectCharacter(params.nodes[0]);
      }
    });

    setNetwork(newNetwork);

    // 清理函数
    return () => {
      if (newNetwork) {
        newNetwork.destroy();
      }
    };
  }, [data, onSelectCharacter]);

  return (
    <div 
      ref={networkRef} 
      style={{ 
        width: '100%', 
        height: height, 
        border: '1px solid #ddd', 
        borderRadius: '8px',
        background: '#f9f9f9'
      }}
    />
  );
};

export default CharacterNetwork;
